CREATE DATABASE IF NOT EXISTS kantin_pos_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kantin_pos_db;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, nama VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'admin');
CREATE TABLE IF NOT EXISTS kategori (id INT AUTO_INCREMENT PRIMARY KEY, nama_kategori VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS barang (id INT AUTO_INCREMENT PRIMARY KEY, nama_barang VARCHAR(150) NOT NULL, kategori_id INT NULL, harga DECIMAL(12,2) NOT NULL DEFAULT 0, stok INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (kategori_id) REFERENCES kategori(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS transaksi (id INT AUTO_INCREMENT PRIMARY KEY, kode_transaksi VARCHAR(40) NOT NULL UNIQUE, total DECIMAL(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS detail_transaksi (id INT AUTO_INCREMENT PRIMARY KEY, transaksi_id INT NOT NULL, barang_id INT NOT NULL, jumlah INT NOT NULL, harga DECIMAL(12,2) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, FOREIGN KEY (transaksi_id) REFERENCES transaksi(id) ON DELETE CASCADE, FOREIGN KEY (barang_id) REFERENCES barang(id));
INSERT IGNORE INTO kategori (nama_kategori) VALUES ('Makanan'),('Minuman'),('Lainnya');
